mapper.select:
SELECT id, user_id, product_id, style_id, qty, created_at, updated_at
FROM cart_items
WHERE user_id = #{userId}

SELECT id, user_id, product_id, style_id, qty, created_at, updated_at
FROM cart_items
WHERE user_id = #{userId}
  AND product_id = #{productId}
  AND (style_id = #{styleId} OR (style_id IS NULL AND #{styleId} IS NULL))

mapper.update:
UPDATE cart_items
SET qty = #{qty}, updated_at = NOW()
WHERE id = #{id}

mapper.delete:
DELETE FROM cart_items
WHERE user_id = #{userId}
  AND product_id = #{productId}
  AND (style_id = #{styleId} OR (style_id IS NULL AND #{styleId} IS NULL))
